"""Unit tests for scripts/gen_pricing.py: the merge of audio and per-second rates into the price table."""
import copy
import hashlib
import importlib.util
import json
import pathlib
import tempfile
import unittest

ROOT = pathlib.Path(__file__).resolve().parent.parent
spec = importlib.util.spec_from_file_location("gen_pricing", ROOT / "scripts" / "gen_pricing.py")
gp = importlib.util.module_from_spec(spec)
spec.loader.exec_module(gp)

HEADER = [
    "// Generated by scripts/gen_pricing.py from a Bifrost pricing datasheet. Do not edit.",
    "// Source: test.json, sha256 0, 4 priced entries.",
    "// (The audio columns of two rows were added by hand: an old note.)",
    "// published prices: an old note that the merge replaces.",
]

# key, provider, input, output, cacheRead, cacheWrite, baseModel and, for a ten column row, the audio and per-second columns
ROWS = [
    ["acme-base", "acme", "0.001", "0.002", "0.0001", "", "acme-base"],
    ["acme-live", "acme", "0.003", "0.004", "", "", "acme-live", "", "", ""],
    ["gemini-tts", "vertex_ai", "0.0005", "0.001", "", "", "gemini-tts"],
    ["plain", "acme", "0.1", "0.2", "", "", "plain"],
]

PRICES = {
    "acme-base": {"litellm_provider": "acme", "input_cost_per_token": 0.001, "output_cost_per_token": 0.002,
                  "cache_read_input_token_cost": 0.0001, "input_cost_per_audio_token": 0.00003, "output_cost_per_audio_token": 0.00006},
    "acme-live": {"litellm_provider": "acme", "input_cost_per_token": 0.003, "output_cost_per_token": 0.004, "input_cost_per_second": 0.0005},
    "gemini-tts": {"litellm_provider": "vertex_ai-language-models", "input_cost_per_token": 0.0005, "output_cost_per_token": 0.001,
                   "input_cost_per_audio_token": 0.000002},
}


def write_table(tmp, rows):
    table = pathlib.Path(tmp) / "pricing_data.tov"
    table.write_text(gp.render(HEADER, rows), encoding="utf-8")
    return table


def write_prices(tmp, prices, name="prices.json"):
    path = pathlib.Path(tmp) / name
    raw = json.dumps(prices).encode("utf-8")
    path.write_bytes(raw)
    return path


class MergeTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()

    def tearDown(self):
        self.tmp.cleanup()

    def merge(self, rows, prices, name="prices.json"):
        table = write_table(self.tmp.name, copy.deepcopy(rows))
        path = write_prices(self.tmp.name, prices, name)
        changes, disagreements, skipped = gp.merge(table, path, "2026-10-19")
        header, out = gp.read_table(table)
        return header, out, changes, disagreements, skipped, table, path

    def test_fills_only_the_audio_and_per_second_columns(self):
        _, out, changes, disagreements, skipped, _, _ = self.merge(ROWS, PRICES)
        by_key = {r[0]: r for r in out}
        base = by_key["acme-base"]
        self.assertEqual(len(base), 10)
        self.assertEqual(base[7:10], ["0.00003", "0.00006", ""])
        self.assertEqual(base[2:7], ["0.001", "0.002", "0.0001", "", "acme-base"])
        self.assertEqual(by_key["acme-live"][9], "0.0005")
        self.assertEqual(by_key["acme-live"][2:7], ["0.003", "0.004", "", "", "acme-live"])
        # a vertex row is matched under the table's name for its provider
        self.assertEqual(by_key["gemini-tts"][7], "0.000002")
        self.assertEqual(by_key["gemini-tts"][2:7], ["0.0005", "0.001", "", "", "gemini-tts"])
        # a row the price file does not have is untouched and keeps seven columns
        self.assertEqual(by_key["plain"], ["plain", "acme", "0.1", "0.2", "", "", "plain"])
        self.assertIn(("acme-base", "input_cost_per_audio_token", None, "0.00003"), changes)
        self.assertIn(("acme-live", "input_cost_per_second", None, "0.0005"), changes)
        self.assertEqual(disagreements, [])
        self.assertEqual(skipped, [])

    def test_token_rates_are_never_changed_and_disagreements_are_reported(self):
        rows = copy.deepcopy(ROWS)
        rows[0][2] = "0.0015"
        prices = copy.deepcopy(PRICES)
        prices["acme-base"]["cache_creation_input_token_cost"] = 0.0002
        _, out, changes, disagreements, _, _, _ = self.merge(rows, prices)
        base = out[0]
        self.assertEqual(base[2], "0.0015")
        self.assertEqual(base[5], "")
        self.assertIn(("acme-base", "input_cost_per_token", "0.0015", 0.001), disagreements)
        self.assertIn(("acme-base", "cache_creation_input_token_cost", None, 0.0002), disagreements)
        self.assertTrue(all(c[1] not in ("input_cost_per_token", "output_cost_per_token") for c in changes))

    def test_a_row_under_another_provider_is_skipped(self):
        rows = copy.deepcopy(ROWS)
        rows[1][1] = "other-co"
        _, out, changes, _, skipped, _, _ = self.merge(rows, PRICES)
        self.assertEqual(len(skipped), 1)
        self.assertIn("acme-live", skipped[0])
        self.assertEqual(out[1][0:2], ["acme-live", "other-co"])
        self.assertEqual(len(out[1]), 10)
        self.assertEqual(out[1][9], "")
        self.assertFalse(any(c[0] == "acme-live" for c in changes))

    def test_a_bare_key_falls_back_to_the_provider_prefixed_one(self):
        rows = [["gemini-3", "gemini", "0.000001", "0.000002", "", "", "gemini-3"]]
        prices = {"gemini/gemini-3": {"litellm_provider": "gemini", "input_cost_per_token": 0.000001,
                                      "output_cost_per_token": 0.000002, "input_cost_per_second": 0.00005}}
        _, out, changes, _, _, _, _ = self.merge(rows, prices)
        self.assertEqual(out[0][9], "0.00005")
        self.assertEqual(changes, [("gemini-3", "input_cost_per_second", None, "0.00005")])

    def test_a_second_merge_changes_nothing(self):
        _, _, _, _, _, table, path = self.merge(ROWS, PRICES)
        first = table.read_text(encoding="utf-8")
        changes, disagreements, skipped = gp.merge(table, path, "2026-10-19")
        self.assertEqual(changes, [])
        self.assertEqual(disagreements, [])
        self.assertEqual(skipped, [])
        self.assertEqual(table.read_text(encoding="utf-8"), first)

    def test_the_header_keeps_the_source_and_records_the_merge(self):
        header, _, _, _, _, table, path = self.merge(ROWS, PRICES, name="litellm-prices.json")
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        self.assertEqual(header, HEADER[:2])
        text = table.read_text(encoding="utf-8")
        self.assertIn("// Audio and per-second columns merged from litellm-prices.json (sha256 %s, 2026-10-19)" % digest, text)
        self.assertNotIn("an old note", text)
        self.assertNotIn("(The audio columns", text)

    def test_the_written_body_round_trips(self):
        odd = [["odd`key${x}\\y", "acme", "0.1", "0.2", "", "", "odd"]]
        table = write_table(self.tmp.name, odd)
        header, rows = gp.read_table(table)
        self.assertEqual(rows, odd)
        self.assertEqual(gp.render(header, rows), gp.render(HEADER[:2], odd))

    def test_the_committed_table_round_trips(self):
        header, rows = gp.read_table(gp.OUT)
        self.assertTrue(all(len(r) in (7, 10) for r in rows))
        again = gp.render(header, rows)
        self.assertEqual(again.partition(gp.EXPORT)[2], gp.OUT.read_text(encoding="utf-8").partition(gp.EXPORT)[2])


if __name__ == "__main__":
    unittest.main()
